  "raised_bed_soil_volume": 288,
  "items": [
    {
      "seedling_id": "A",
      "soil_volume_per_seedling": 69,
      "expected_harvest_value": 8
    },
    {
      "seedling_id": "B",
      "soil_volume_per_seedling": 93,
      "expected_harvest_value": 47
    },
    {
      "seedling_id": "C",
      "soil_volume_per_seedling": 75,
      "expected_harvest_value": 80
    },
    {
      "seedling_id": "D",
